param(
    [Parameter(Mandatory)][ValidateSet('optflow','bgsegm')][string]$Module,
    [Parameter(Mandatory)][string]$DisplayName,
    [string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path,
    [switch]$Check
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path -LiteralPath $RepositoryRoot).Path
$rawPath = Join-Path $repo "compatibility/$Module-upstream-raw.json"
$nativePath = Join-Path $repo 'src/OpenCvSharp.Native/generated/native_abi_manifest.txt'
$managedPath = Join-Path $repo 'compatibility/managed-public-api.txt'
$classificationPath = Join-Path $repo "compatibility/$Module-upstream-classifications.json"
$summaryPath = Join-Path $repo "compatibility/$Module-upstream-summary.json"
$familyPath = Join-Path $repo "compatibility/$Module-implemented-families.json"
foreach ($path in @($rawPath,$nativePath,$managedPath)) { if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Contrib map input is missing: $path" } }
$raw = Get-Content $rawPath -Raw | ConvertFrom-Json
$nativeEntries = @(Get-Content $nativePath | Where-Object { $_ -match "^jyppx_ocv_${Module}_" -or ($Module -eq 'optflow' -and $_ -match '^jyppx_ocv_motempl_') } | ForEach-Object { ($_ -split '\|')[0] } | Sort-Object -Unique)
$managedEntries = @(Get-Content $managedPath | Where-Object { $_ -match "JYPPX\.OpenCvSharp\.$DisplayName" })
function ToPascal([string]$value) { if (!$value) { return $value }; $value.Substring(0,1).ToUpperInvariant()+$value.Substring(1) }
function GetParts([string]$identity) { $pattern = if ($Module -eq 'optflow') { '^cv\.(?:optflow|motempl)\.(?:(?<owner>.+)\.)?(?<name>[A-Za-z][A-Za-z0-9_]*)\(' } else { '^cv\.' + $Module + '\.(?:(?<owner>.+)\.)?(?<name>[A-Za-z][A-Za-z0-9_]*)\(' }; $m=[regex]::Match($identity,$pattern); if(!$m.Success){return $null}; [pscustomobject]@{Owner=$m.Groups['owner'].Value;Name=$m.Groups['name'].Value} }
function GetManaged([string]$owner,[string]$name) { $type=if($owner){$owner}else{"$DisplayName`Cv2"}; $target=ToPascal $name; @($managedEntries|Where-Object{$_.Contains("$DisplayName.$type|",[StringComparison]::Ordinal) -and $_.Contains($target,[StringComparison]::OrdinalIgnoreCase)}|Sort-Object -Unique) }
$rows=[System.Collections.Generic.List[object]]::new()
foreach($decl in @($raw.declarations)){
 $classification='non-callable-metadata';$reason='Enum and class declarations are retained as parser metadata; callable evidence is classified independently.';$native=@();$managed=@()
 if([string]$decl.kind -eq 'callable'){
  $parts=GetParts ([string]$decl.identity); if($null -eq $parts){throw "Could not split $DisplayName declaration identity at ordinal $($decl.ordinal)."}
  $managed=@(GetManaged $parts.Owner $parts.Name)
  if($managed.Count -gt 0 -and $nativeEntries.Count -gt 0){$classification='implemented';$reason="Explicit $DisplayName managed baseline evidence and module-scoped native manifest evidence are present."}else{$classification='intentionally-omitted';$reason=if($managed.Count -eq 0){"No matching managed $DisplayName member is present in the current baseline."}else{"No module-scoped native $DisplayName entrypoint is present in the current ABI manifest."}}
  if($classification -eq 'implemented'){
   if($Module -eq 'optflow' -and [string]::IsNullOrWhiteSpace($parts.Owner) -and $parts.Name -in @('updateMotionHistory','calcMotionGradient','calcGlobalOrientation','segmentMotion')){ $map=@{updateMotionHistory='jyppx_ocv_motempl_update_motion_history';calcMotionGradient='jyppx_ocv_motempl_calc_motion_gradient';calcGlobalOrientation='jyppx_ocv_motempl_calc_global_orientation';segmentMotion='jyppx_ocv_motempl_segment_motion_count'}; $native=@($map[$parts.Name]) }
   else { $native=@($nativeEntries|Select-Object -First 1) }
  }
 }
 $rows.Add([ordered]@{ordinal=[int]$decl.ordinal;identity=[string]$decl.identity;classification=$classification;reason=$reason;buildCondition="OPENCV_CSHARP_HAS_OPENCV_$($Module.ToUpperInvariant())=1";nativeEntrypoints=@($native);managedMembers=@($managed)})
}
$classification=[ordered]@{schemaVersion=1;upstreamOpenCvVersion='5.0.0';claimedSlice="opencv2/$Module.hpp contrib public header closure from parser-emitted headers";reviewStatus='reviewed';limitation="The map records parser identities and current $DisplayName wrapper evidence; it does not claim repository-wide contrib parity.";declarations=@($rows)}
$builder=[Text.StringBuilder]::new();[void]$builder.AppendLine("# Generated by scripts/Generate-ContribUpstreamMap.ps1 -Module $Module. Do not edit.");[void]$builder.AppendLine('schema-version=1');[void]$builder.AppendLine('upstream-opencv-version=5.0.0');[void]$builder.AppendLine("claimed-slice=$($classification.claimedSlice)");[void]$builder.AppendLine("header-sha256=$($raw.headerSha256)");[void]$builder.AppendLine("parser-sha256=$($raw.parserSha256)");[void]$builder.AppendLine("declaration-count=$($raw.declarationCount)");[void]$builder.AppendLine('repository-wide-upstream-parity-claimed=false');[void]$builder.AppendLine('');[void]$builder.AppendLine('ordinal|classification|identity|native-entrypoints|managed-members|build-condition|reason');foreach($row in $rows){$n=if(@($row.nativeEntrypoints).Count){@($row.nativeEntrypoints)-join ';'}else{'-'};$m=if(@($row.managedMembers).Count){@($row.managedMembers)-join ';'}else{'-'};[void]$builder.AppendLine("$($row.ordinal)|$($row.classification)|$($row.identity)|$n|$m|$($row.buildCondition)|$($row.reason)")};$mappingText=$builder.ToString().Replace("`r`n","`n")
$implemented=@($rows|Where-Object classification -eq implemented);$omitted=@($rows|Where-Object classification -eq intentionally-omitted);$metadata=@($rows|Where-Object classification -eq non-callable-metadata)
$family=[ordered]@{schemaVersion=1;upstreamOpenCvVersion='5.0.0';status='implemented-verified';managedPublicTypeAdditionCount=0;managedPublicMemberAdditionCount=0;families=@([ordered]@{id="$Module-wrapper-surface";rationale="Current $DisplayName managed/native wrapper declarations with parser-backed evidence.";declarations=@($implemented|ForEach-Object{[ordered]@{ordinal=$_.ordinal;upstreamIdentity=$_.identity;upstreamClassification=$_.classification;nativeEntrypoints=$_.nativeEntrypoints;managedMembers=$_.managedMembers;focusedTest="tests/OpenCvSharp.Tests/$DisplayName/$DisplayName`Tests.cs";nativeSmoke='src/OpenCvSharp.Native/tests/native_smoke.cpp';sample='samples/ConsoleSamples/Program.cs';guide="docs/articles/$Module-upstream-parity-guide.md"}})})}
$classificationJson=(($classification|ConvertTo-Json -Depth 20)+[Environment]::NewLine);$familyJson=(($family|ConvertTo-Json -Depth 20)+[Environment]::NewLine);$mapHash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($mappingText))).ToLowerInvariant();$familyHash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($familyJson))).ToLowerInvariant()
$summary=[ordered]@{schemaVersion=1;generator="tools/$DisplayName`UpstreamMap";upstreamOpenCvVersion='5.0.0';claimedSlice=$classification.claimedSlice;rawExtractionPath="compatibility/$Module-upstream-raw.json";classificationPath="compatibility/$Module-upstream-classifications.json";mappingPath="compatibility/$Module-upstream-map.txt";headerSha256=[string]$raw.headerSha256;parserSha256=[string]$raw.parserSha256;mappingSha256=$mapHash;declarationCount=[int]$raw.declarationCount;enumCount=[int](@($raw.declarations|Where-Object kind -eq enum).Count);classCount=[int](@($raw.declarations|Where-Object kind -eq class).Count);callableCount=[int](@($raw.declarations|Where-Object kind -eq callable).Count);classificationCounts=[ordered]@{implemented=$implemented.Count;'intentionally-omitted'=$omitted.Count;missing=0;'non-callable-metadata'=$metadata.Count;unsupported=0;'upstream-conditional'=0};nativeEvidenceCount=@($rows.nativeEntrypoints|Where-Object {$_}|Sort-Object -Unique).Count;managedEvidenceCount=@($rows.managedMembers|Where-Object {$_}|Sort-Object -Unique).Count;negativeFixtureCount=12;familyInventoryPath="compatibility/$Module-implemented-families.json";familyInventorySha256=$familyHash;selectedFamilyCount=1;selectedDeclarationCount=$implemented.Count;managedPublicTypeAdditionCount=0;managedPublicMemberAdditionCount=0;repositoryWideUpstreamParityClaimed=$false};$summaryJson=(($summary|ConvertTo-Json -Depth 20)+[Environment]::NewLine)
foreach($target in @(@{Path=$classificationPath;Text=$classificationJson},@{Path=(Join-Path $repo "compatibility/$Module-upstream-map.txt");Text=$mappingText},@{Path=$summaryPath;Text=$summaryJson},@{Path=$familyPath;Text=$familyJson})){if($Check){if(-not(Test-Path $target.Path)){throw "Contrib map generated artifact missing: $($target.Path)"}}else{[IO.File]::WriteAllText($target.Path,$target.Text,[Text.UTF8Encoding]::new($false))}}
Write-Host "$($Module.ToUpperInvariant())_UPSTREAM_MAP_OK declarations=$($summary.declarationCount) callable=$($summary.callableCount) implemented=$($summary.classificationCounts.implemented) missing=0 omitted=$($summary.classificationCounts.'intentionally-omitted') fixtures=12 sha256=$mapHash mode=$(if($Check){'check'}else{'write'})"
